data.query:
query (
  $where: ProductionSetupOutputWhereInput!,
  $workcenterIds: [String!]!
){
  productionSetupOutput( where: $where )
   {
    edges {
      node {
        id
        workcenterId
        productName
        productNumber
        productRevision
        productNumberRevision
        operationCode
        operationNumber

        workOrderNumber

        productOperationId
        productId

        producedQuantity
        scrappedQuantity

        idealRate
        standardRate
        productionSetup{
          productionRunId
          mode{
            includeProductionCounts
          }
        }
      }
    }
  }

  shiftGroup(
    where:{
      workcenters:{
        _some:{id:{ _in: $workcenterIds}}
      }
    }
  ){
    edges{
      node{
        id
        shifts(
          where:{
            active:{_eq: true}
          }
        ){
          edges{
            node{
              id
              name
              creditAtStart
              monday
              tuesday
              wednesday
              thursday
              friday
              saturday
              sunday
              startHour
              startMinute
              endHour
              endMinute
            }
          } 
        }
				workcenters(
          where:{
            id:{ _in: $workcenterIds}
          }
        ){
          edges{
            node { id }
          }
        }
      }
    }
  }

  setting(
    where:{
      id:{_eq: "TimeZone"}
    }
  ){
    edges{
      node{
				id
        defaultValue
      }
    }
  }
}

data.transform:
(

  $timeZone := $.setting.edges.node.defaultValue;
  $now := $moment().format();

  $findCreditAt := function($date, $shift){(
    $dateInTimeZone := $momentTz($date, undefined, $timeZone);
    /* $dateInTimeZone := $moment($$.date); */
    $crrHour := $dateInTimeZone.hour();
    $crrMinute := $dateInTimeZone.minute();

    /* If we're after midnight, we'd need to subtract a day. */
    $offsetToMakeDateBeOnStartOfShift := $crrHour < $shift.startHour ? -1 : 0;

    /* If we're before midnight, we'd need to add a day. */
    $offsetToMakeDateBeOnEndOfShift := $crrHour < $shift.startHour ? 0 : 1;

    /* If the shift "starts" after it "ends", it bridges midnight. */
    $shiftBridgesMidnight := $shift.startHour > $shift.endHour;

    /* 
      LMENARD 11-2-22
      Decide which offset to use based on the creditAtStart flag on the shift. 
      If the shift doesn't bridge midnight, we don't need to adjust anything at all.
      I feel like this whole thing could be simpler...
    */
    $offsetToUse := $shiftBridgesMidnight 
      ? $shift.creditAtStart ? $offsetToMakeDateBeOnStartOfShift : $offsetToMakeDateBeOnEndOfShift
      : 0;

    $dateInTimeZone.add($offsetToUse, "day").startOf("day").format();

  )};

  $findShift := function($date, $shifts){(

    $allShifts := $shifts;
    $shift := $filter(
      $allShifts,
      function($v){(
        $dateInTimeZone := $momentTz($date, undefined, $timeZone);
        /* $dateInTimeZone := $moment($$.date); */
        $crrHour := $dateInTimeZone.hour();
        $crrMinute := $dateInTimeZone.minute();
        $dayOfWeek := $dateInTimeZone.format("dddd")~>$lowercase;

        $lookup($v, $dayOfWeek) and
        (
          /* Logic for when the shift starts and ends on the same day*/
          (
            (
              $v.startHour < $v.endHour and
              (
                  $v.startHour < $crrHour or
                  (
                    $v.startHour = $crrHour and
                    $v.startMinute <= $crrMinute
                  )

              ) and
              (
                $v.endHour > $crrHour or
                (
                  $v.endHour = $crrHour and
                  $v.endMinute > $crrMinute
                )
              )
            )
            or
            /* Logic for when the shift starts and ends on different day*/
            (
              $v.startHour > $v.endHour and
              (

                  $v.startHour < $crrHour or
                  (
                    $v.startHour = $crrHour and
                    $v.startMinute <= $crrMinute
                  ) or
                  (
                    $v.endHour > $crrHour or
                    (
                      $v.endHour = $crrHour and
                      $v.endMinute > $crrMinute
                    )
                  )
              )

            )
          )
        )
      )}
    );

    $shift~>| $ | { "creditAt": $findCreditAt($date, $shift) } |

  )};

  $preData := $leftOuterJoin( 
    [$state.context.payload], 
    [productionSetupOutput.edges.node], 
    "workcenterId", 
    'workcenterId', 
    'setupOutput'
  );

  /* Sort out which requests need serial numbers and which ones are provided*/
  $needSerials := $preData[$isNilOrEmpty(options.serialNumber)];
  $hasSerials := $preData[$isNilOrEmpty(options.serialNumber)~>$not];

  $numberOfNeededSerials := $count($needSerials) - 1;
  $serialPayload := [0..$numberOfNeededSerials].{
    "where":{
      "name": "Serial Numbers"
    }
  };

  /* Get the serial numbers from the seqeunce*/
  $serialNumbers := $mutate({
    "statement": "mutation ($payload: [GenerateSequenceNumberPayloadInput!]!){\n  generateSequenceNumber(payload: $payload) { value }\n}",
    "variables":{
      "payload": [$serialPayload]
    }
  }).generateSequenceNumber.value;

  /* Added the generated serials to the requests that do not have them.*/
  $addedSerials := $needSerials#$i.(
    $~>| options | {"serialNumber": $serialNumbers[$i]} |
  );

  $data := $append($addedSerials, $hasSerials);

  /* Create api payloads */
  $productionHistoryPayload := $data.(

    $workcenterId := workcenterId;
    $shifts := $filter($$.shiftGroup.edges.node, function($v){$workcenterId in [$v.workcenters.edges.node.id] }).shifts.edges.node;
    $shift := $findShift($now, $shifts);

    {
      "create":{
        "quantity": quantity,
        "standardRate": setupOutput.standardRate,
        "idealRate": setupOutput.idealRate,
        "employeeName": options.employeeName,
        "heatCode": options.heatCode,
        "lotNo": options.lotNo,
        "masterUnitNo": options.masterUnitNo,
        "operationCode": setupOutput.operationCode,
        "operationNumber": setupOutput.operationNumber,
        "productNumber": setupOutput.productNumber,
        "productRevision": setupOutput.productRevision,
        "productNumberRevision": setupOutput.productNumberRevision,
        "productionRunId": setupOutput.productionSetup.productionRunId,
        "serialNo": options.serialNumber,
        "trackingNo": options.trackingNo,
        "unit": options.unit,
        "workOrderNumber": setupOutput.workOrderNumber,
        "occurAt": $now,
        "transactionTypeId": type="production"? "Production Add" : "Scrap Add",
        "scrapReasonId": type = "scrap"? options.scrapReasonId,
        "workcenterId": workcenterId,
        "shiftId": $coalesce([ $shift.id, "offShift"]),
        "creditedAt": $coalesce([ $shift.creditAt, $moment().startOf("day").format()]),
        "includeInProductionCounts": setupOutput.productionSetup.mode.includeProductionCounts = true,
        "approvedWorkcenterId": $hash("SHA256", $join([workcenterId, setupOutput.productNumberRevision, setupOutput.operationCode,  setupOutput.operationNumber], "::")),
        "id": $hash(
          "SHA256", 
          $join([
            workcenterId, 
            $now, 
            setupOutput.productNumberRevision, 
            options.serialNumber
          ], "::") )
      }
    } 
  );

  $setupPayload := $groupBy($preData, function($v){
    $join([
      $v.workcenterId, 
      $string($v.outputId) ,
      $v.type
      ], "::")
  })
      ~>$mapValues(
      function($v){(
        $setupOutput := $first($v).setupOutput;
        $type := $first($v).type;
        $scrappedQuantity := $coalesce([$setupOutput.scrappedQuantity, 0]);
        $producedQuantity := $coalesce([$setupOutput.producedQuantity, 0]);

        {
          "where":{ "id": $setupOutput.id},
          "update":{
            "scrappedQuantity": $type="scrap"? $scrappedQuantity + $sum($v.quantity),
            "producedQuantity": $type="production"? $producedQuantity + $sum($v.quantity)
          }
        }
      )}
    )
    ~>$values;

  {
      "setupPayload": $setupPayload,
      "productionHistoryPayload": $productionHistoryPayload
  }  
)

(

  $intergrationMessage := $tryCatch (
    function(){
      $executeFlow(
        $appConfig.machineMonitoring.productionHistory.intergration.flowId,
        {
          "payload": $state.context.payload,
          "fuuzData": productionHistoryPayload.create
        }
      )
    },
    function($err){ $err.**.jse_shortmsg }
  )();

  {
    "api": $,  /* return the api payload*/
    "intergrationMessage": $intergrationMessage
  }

)

